using System.Text.Json.Serialization;

namespace Square.Models;

/// <summary>
/// Defines the fields that are included in the request body of a request
/// to the <c>CreateCustomerCard</c> endpoint.
/// </summary>
public record CreateCustomerCardRequest
{
    /// <summary>
    /// A card nonce representing the credit card to link to the customer.
    /// <para>
    /// Card nonces are generated by the Square payment form when customers enter
    /// their card information. For more information, see
    /// <see href="https://developer.squareup.com/docs/web-payments/take-card-payment">Walkthrough: Integrate Square Payments in a Website</see>.
    /// </para>
    /// <para>
    /// __NOTE:__ Card nonces generated by digital wallets (such as Apple Pay)
    /// cannot be used to create a customer card.
    /// </para>
    /// </summary>
    [JsonPropertyName("card_nonce")]
    public required string CardNonce { get; init; }

    /// <summary>
    /// Represents a postal address in a country.
    /// For more information, see <see href="https://developer.squareup.com/docs/build-basics/working-with-addresses">Working with Addresses</see>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("billing_address")]
    public Address? BillingAddress { get; init; }

    /// <summary>
    /// The full name printed on the credit card.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("cardholder_name")]
    public string? CardholderName { get; init; }

    /// <summary>
    /// An identifying token generated by <see href="https://developer.squareup.com/reference/sdks/web/payments/objects/Payments#Payments.verifyBuyer">Payments.verifyBuyer()</see>.
    /// Verification tokens encapsulate customer device information and 3-D Secure
    /// challenge results to indicate that Square has verified the buyer identity.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("verification_token")]
    public string? VerificationToken { get; init; }
}
